"""Sum of Scores of Built Strings — Z-algorithm.

The score of the prefix of length i is the longest common prefix between s and
its suffix starting at n - i, which is exactly a Z-array entry.

Time: O(n)   Space: O(n)
"""


class Solution:
    def sumScores(self, s: str) -> int:
        n = len(s)
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]
        return sum(z)
